<h3>A: CHEQUE/ TRANSFER PAYMENTS </h3>
<table class="invoice-table">
    <thead>
        <tr>
            <th style="width:5%;">No</th>
            <th style="width:20%;">Supplier</th>
            <th style="width:45%;">Particulars</th>
            <th style="width:30%;">Payment Amount</th>
        </tr>
    </thead>
    <tbody>
        {% set ns = namespace(subtotal=0) %}

        {% for item in doc.cheque_transfer_payments %}

            {% if item.heading %}
                {% if ns.subtotal > 0 %}
                    <tr>
                        <th colspan="6" style="text-align:right"><strong>Subtotal &nbsp;&nbsp;{{ frappe.utils.fmt_money(ns.subtotal, currency=doc.currency) }}</strong></th>
                    </tr>
                    {% set ns.subtotal = 0 %}
                {% endif %}
                <tr>
                    <th style="text-align:left" colspan="6">{{ item.heading }}</th>
                </tr>
            {% endif %}

            <tr>
                <td class="text-center">{{ loop.index }}</td>

                <td>
                    {{ item.supplier }}
                </td>

                <td class="text-center">
                    {{ item.particulars }}
                </td>

                <td class="text-right">
                    {{ item.get_formatted("amount", doc) }}
                </td>
            </tr>

            {% set ns.subtotal = ns.subtotal + (item.amount or 0) %}

        {% endfor %}

        {% if ns.subtotal > 0 %}
            <tr>
                <th colspan="5" class="text-right">Subtotal</th>
                <th class="text-right">{{ frappe.utils.fmt_money(ns.subtotal, currency=doc.currency) }}</th>
            </tr>
        {% endif %}
    </tbody>
</table>
